import type { Document, Root } from "postcss";
import type { PostcssResult } from "stylelint";
/** The texts a lineness rule reads, innermost first; `linenessRank` packs the index as one character. */
declare const TEXTS: readonly [`call`, `declaration`, `statement`];
/** A rule's lineness text. */
export type Text = typeof TEXTS[number];
/** Every lineness-conditioned rule: the text it counts lines of, and whether its subject is a break; the test beside checks the table. */
export declare const LINENESS_RULES: Record<string, [text: Text, speaksOfABreak: boolean]>;
/**
 * Orders two ranks.
 * @param one - One rank.
 * @param other - The rank compared against.
 * @returns As `sort` wants.
 */
export declare function compareRanks(one: string, other: string): number;
/**
 * Ranks a deferred check, so that the plugin rather than the configuration decides the order.
 *
 * String order is run order:
 *
 * - the text the check reads, innermost first;
 * - checks about a line break;
 * - checks conditioned on a single-line text;
 * - the rule's name, then its namespace, the core's first.
 *
 * The middle two were measured: of the orders four criteria make, this asks least before the name and leaves no corpus row unsatisfied. The joining space sorts below every character of a name.
 * @param shortName - The rule's name without its namespace.
 * @param namespace - None for the core's.
 * @param primary - One not about lineness ranks as multi-line.
 * @returns The rank.
 */
export declare function linenessRank(shortName: string, namespace: string | undefined, primary: string): string;
/**
 * Asks whether a primary defers its check to the run's end: `-single-line` and `-multi-line` read a lineness another rule may still change.
 * @param primary - The rule's configured primary, of any type.
 * @returns True where the check waits.
 */
export declare function defersToRunEnd(primary: unknown): boolean;
/**
 * Records a rule name as built.
 * @param ruleName - The configured name.
 */
export declare function registerPluginRule(ruleName: string): void;
/**
 * Returns the last plugin rule this run calls, where the deferred checks flush; rules run in the configuration's order, those off or never built skipped.
 * @param result - Holds the configuration.
 * @returns The name, or nothing.
 */
export declare function lastConfiguredPluginRule(result: PostcssResult): string | undefined;
/**
 * Defers a check to this root's flush.
 * @param root - The root whose flush runs the check.
 * @param rank - From `linenessRank`.
 * @param run - The check.
 */
export declare function deferCheck(root: Document | Root, rank: string, run: () => void): void;
/**
 * Asks whether a check runs at the head of a root's flush, ahead of the lineness tier.
 * @param root - The root the check reads.
 * @returns True during the head.
 */
export declare function runsAtTheHead(root: Document | Root): boolean;
/**
 * Defers a check ahead of the lineness tier, so that the tier reads the breaks it writes.
 * @param root - The root whose flush runs the check.
 * @param rank - From `linenessRank`.
 * @param run - The check.
 */
export declare function deferHeadCheck(root: Document | Root, rank: string, run: () => void): void;
/**
 * Defers a check behind the lineness tier, which writes breaks too.
 * @param root - The root whose flush runs the check.
 * @param rank - From `linenessRank`.
 * @param run - The check.
 */
export declare function deferFinalCheck(root: Document | Root, rank: string, run: () => void): void;
/**
 * Runs this root's deferred checks, the head first, then the lineness tier, then the reading one, each in rank order; every queue sorts, since a rule under two namespaces reads a plain CSS root twice.
 * @param root - The root whose queued checks run.
 */
export declare function flushDeferredChecks(root: Document | Root): void;
export {};
